//
// channel/keep-list.txt of FreeMixer/.github, read by the prune: the versions our own work pins (generated by
// that repository's channel/gen-keep-list.mjs, never by hand). Lines are "<package> <version> <distro/arch> <pin>",
// tab separated; see the generator for the version forms. This module
//   - refuses a file whose lines do not match its "# sum" (a hand edit, or a generator bypassed),
//   - turns exact lines into keep entries (the prune keeps those builds beside the newest ones),
//   - names every line the channel does not serve (a missing pin: the channel lost, or never had, a version a
//     pin still names).
import crypto from 'node:crypto';
import { rpmvercmp, debVersionCmp, parseDebVersion, sourceName, whereMatches } from './prune.mjs';

export function parseKeepList(text) {
  const lines = [];
  let sum = null, header = false;
  for (const raw of text.split('\n')) {
    if (!raw.trim()) continue;
    const m = raw.match(/^# sum ([0-9a-f]{64})$/);
    if (m) { sum = m[1]; continue; }
    if (raw.startsWith('#')) { if (/^# GENERATED by channel\/gen-keep-list\.mjs/.test(raw)) header = true; continue; }
    const f = raw.split('\t');
    if (f.length !== 4 || f.some((x) => !x.trim())) throw new Error(`keep-list: not "package<TAB>version<TAB>distro/arch<TAB>pin": ${JSON.stringify(raw)}`);
    if (!/^(newest|>=\S+|\d\S*)$/.test(f[1])) throw new Error(`keep-list: bad version ${JSON.stringify(f[1])} in ${JSON.stringify(raw)}`);
    lines.push({ pkg: f[0], version: f[1], where: f[2], pin: f[3] });
  }
  if (!header) throw new Error('keep-list: no GENERATED header: the file is made by channel/gen-keep-list.mjs');
  const want = crypto.createHash('sha256').update(lines.map((l) => [l.pkg, l.version, l.where, l.pin].join('\t')).join('\n') + '\n').digest('hex');
  if (sum !== want) throw new Error('keep-list: the lines do not match the "# sum": edited by hand, or not made by the generator');
  return lines;
}

const distroRepo = (where) => where.split('/').slice(0, 2).join('/'); // fedora/44/* -> fedora/44, debian/bookworm/amd64 -> debian/bookworm
const formatOf = (where) => (where.startsWith('fedora') ? ['rpm'] : where.startsWith('debian') ? ['deb'] : ['rpm', 'deb']);
const whereRepo = (where) => { const r = distroRepo(where); return r.endsWith('/*') || r === '*' ? r.replace(/\/?\*$/, '') || '*' : r; };

// exact lines -> keep entries
export function keepEntries(lines) {
  const out = [];
  for (const l of lines) {
    if (l.version === 'newest' || l.version.startsWith('>=')) continue;
    const [version, ...rel] = l.version.split(/-(.*)/s);
    const e = { version, where: whereRepo(l.where), reason: `${l.pin}` };
    if (rel[0]) e.release = rel[0];
    if (l.pkg.startsWith('source:')) e.source = [l.pkg.slice(7)];
    else for (const f of formatOf(l.where)) e[f] = [l.pkg];
    out.push(e);
  }
  return out;
}

const upstream = (p) => (p.format === 'rpm' ? p.evr.ver : parseDebVersion(p.evr).upstream);
const releaseOf = (p) => (p.format === 'rpm' ? p.evr.rel : parseDebVersion(p.evr).revision);
const vcmp = (p, v) => (p.format === 'rpm' ? rpmvercmp(upstream(p), v) : debVersionCmp(upstream(p), v));

// the lines the channel cannot serve: allPkgs are every package of every repository read
export function missing(lines, allPkgs) {
  const out = [];
  for (const l of lines) {
    const archOk = (p) => { const a = l.where.split('/')[2]; return !a || a === '*' || p.arch === a || p.arch === 'noarch' || p.arch === 'all'; };
    const mine = allPkgs.filter((p) => p.arch !== 'src' && formats(l).includes(p.format) && whereMatches(whereRepo(l.where), p.repo) && archOk(p)
      && (l.pkg.startsWith('source:') ? sourceName(p) === l.pkg.slice(7) : p.name === l.pkg));
    let ok;
    if (l.version === 'newest') ok = mine.length > 0;
    else if (l.version.startsWith('>=')) ok = mine.some((p) => vcmp(p, l.version.slice(2)) >= 0);
    else {
      const [v, ...r] = l.version.split(/-(.*)/s);
      ok = mine.some((p) => upstream(p) === v && (!r[0] || releaseOf(p) === r[0] || releaseOf(p).startsWith(r[0] + '.')));
    }
    if (!ok) out.push(`${l.pkg} ${l.version} ${l.where}: the channel serves no such version (pin: ${l.pin})`);
  }
  return out;
}
const formats = (l) => formatOf(l.where);
